<script setup lang="ts">import{ref}from'vue';import{useChat}from'./useChat';import ChatInput from'./ChatInput.vue';import MessageList from'./MessageList.vue';import TurnstileGate from'./TurnstileGate.vue';defineProps<{page?:string,turnstileSiteKey?:string}>();const chat=useChat();const verified=ref(sessionStorage.getItem('nw-qa-verified')==='1');function ready(){verified.value=true;sessionStorage.setItem('nw-qa-verified','1')}</script>
<template><TurnstileGate v-if="!verified" :site-key="turnstileSiteKey" @ready="ready"/><section v-else class="grid gap-4"><MessageList :messages="chat.messages.value" /><p v-if="chat.progress.value" class="text-sm text-muted">{{ chat.progress.value }}</p><p v-if="chat.error.value" class="text-danger">{{ chat.error.value }}</p><ChatInput :disabled="chat.sending.value" @send="value=>chat.send(value,page)" @stop="chat.stop" /><button v-if="chat.messages.value.length" type="button" class="text-sm text-muted" @click="chat.clear">清空对话</button></section></template>
